import logging
import re
import six
import taf.rfrl.utilities.logger.custom_logger as logger
from taf.rfrl.bts.helpers.singleton import Singleton
from taf.rfrl.bts.devices.du.commissioning import GenericCommissioning
from taf.rfrl.bts.devices.generic_bts import login_logout


class GenericCable(GenericCommissioning):
    def create_cablink_instance(self, delta, bts_id=0, skip_parameter_relation_errors=False, should_activate=True,
                                timeout=600, adjust_dist_name=True, log_hierarchy=3):
        """
        Create cablink object in BTS
        :param delta: list of parameters required to create a new cablink instance
        :param bts_id: BTS id
        :param skip_parameter_relation_errors: flag whether to skip relation errors. Default False
        :param should_activate: should automatically activate plan
        :param timeout: timeout for delta commissioning operation
        :param adjust_dist_name: flag whether to adjust dist name in delta list
        :param log_hierarchy: log hierarchy
        """
        status = self.perform_bts_delta_commissioning(delta=delta,
                                                      bts_id=bts_id,
                                                      skip_parameter_relation_errors=skip_parameter_relation_errors,
                                                      should_activate=should_activate,
                                                      timeout=timeout,
                                                      adjust_dist_name=adjust_dist_name)
        dist_name = self.adjust_dist_name(dist_name=delta[0]["distName"], bts_id=bts_id)
        logger.log_info_to_console(f'{dist_name} was created.', log_hierarchy=log_hierarchy)
        return status

    def delete_cablink_instance(self, cablink_id, bts_id=0, should_activate=True, skip_parameter_relation_errors=False,
                                timeout=300, log_hierarchy=3):
        """
        Delete cablink object in BTS
        :param cablink_id: cablink id which should be removed from BTS configuration
        :param bts_id: BTS id
        :param skip_parameter_relation_errors: flag whether to skip relation errors
        :param should_activate: should automatically activate plan
        :param timeout: timeout for delta commissioning operation
        :param log_hierarchy: log hierarchy
        """
        dist_name = self.adjust_dist_name(dist_name=f"MRBTS-{{}}/EQM-1/HWTOP-1/CABLINK-{cablink_id}", bts_id=bts_id)
        delta = [{"distName": dist_name, "operation": "delete", "parameters": []}]
        status = self.perform_bts_delta_commissioning(delta=delta,
                                                      bts_id=bts_id,
                                                      skip_parameter_relation_errors=skip_parameter_relation_errors,
                                                      should_activate=should_activate,
                                                      timeout=timeout)
        logger.log_info_to_console(f'{dist_name} was deleted.', log_hierarchy=log_hierarchy)
        return status

    @login_logout
    def get_cablinks_link_mode(self, bts_id=0, du_id=0):
        """
        Get cablinks link mode
        :param bts_id: BTS id
        :param du_id: DU id
        :return: dict with cablinks link mode, example
            {
                "MRBTS-76220/EQM-1/APEQM-1/CABINET-1/BBMOD-1":[
                {
                    "cablink":"MRBTS-76220/EQM-1/HWTOP-1/CABLINK-3",
                    "rf_port":"RF2",
                    "link_mode":{
                        "configuration":false,
                        "data":true,
                        "synchronization":false,
                        "dc":false
                    }
                }
            }
        """
        conn = self.rest_alias.format(bts_id, du_id)
        bts_info = self.admin.get_bts_info(connection=conn)
        cablinks = {}
        cable_info = bts_info['cables']
        logging.info(f'CABLES: {cable_info}')
        pattern = re.compile(r'(?P<mod>.+/(BBMOD|SMOD)-\d+)/(?P<rf_port>RF\d+)')
        for cable in cable_info:
            matched = pattern.match(cable['firstEndPointId']['configuration'])
            if matched:
                mod_dist_name = matched.group('mod')
                if mod_dist_name not in cablinks.keys():
                    cablinks[mod_dist_name] = []
                cablinks[mod_dist_name].append(
                    {
                        'cablink': cable['id']['configuration'],
                        'rf_port': matched.group('rf_port'),
                        'link_mode': cable['linkMode']
                    }
                )
            else:
                logging.debug(f"Not BBMOD|SMOD cable distName: {cable['firstEndPointId']['configuration']}")
        logging.info(f"CABLINKS:\n {cablinks}")
        return cablinks


@six.add_metaclass(Singleton)
class EnbCable(GenericCable):
    """Class contains Cable keywords for eNB"""

    bts_type = 'ENB'

    def __init__(self):
        """
        Constructor of Enb class.

        """

        super(EnbCable, self).__init__(bts_type=EnbCable.bts_type)


@six.add_metaclass(Singleton)
class GnbCable(GenericCable):
    """Class contains Cable keywords for gNB"""

    bts_type = 'GNB'

    def __init__(self):
        """
        Constructor of Gnb class.

        """
        super(GnbCable, self).__init__(bts_type=GnbCable.bts_type)
